  "glossary": [
    {
      "term": "sovereign satellite",
      "definition": "A satellite owned and operated by a country so it controls how and when the data or service is used."
    },
    {
      "term": "proliferated architectures",
      "definition": "Using many smaller satellites instead of a few large ones, so losing one causes less disruption."
    },
    {
      "term": "ground infrastructure (ground segment)",
      "definition": "The earth-based equipment—control centres, antennas, networks—that operate and receive data from satellites."
    },
    {
      "term": "space weather",
      "definition": "Solar activity—like flares—that can disrupt radio signals, increase atmospheric drag and damage satellites."
    },
    {
      "term": "RPO (rendezvous and proximity operations)",
      "definition": "A technique for spacecraft to approach or service other satellites in orbit for repair or refuelling."
    },
    {
      "term": "Carrington event",
      "definition": "An 1859 solar storm often used as a worst-case example of space‑weather damage to modern systems."
    },
    {
      "term": "Kessler syndrome",
      "definition": "A cascade where too much orbital debris causes collisions that create more debris, eventually blocking space use."
    }
  ]
